        files: ['js'],
        starter: {
          html: JSP('  <button id="add-plain">Add plain (3,000)</button>\n  <button id="add-chicken">Add chicken (7,000)</button>\n  <ul id="lines"></ul>\n  <p>Total: UGX <span id="total">0</span></p>'),
          js: 'let cart = JSON.parse(localStorage.getItem("cart") || "[]");\nconst lines = document.querySelector("#lines");\nconst total = document.querySelector("#total");\n\nfunction render() {\n  lines.innerHTML = "";\n  for (const item of cart) {\n    const li = document.createElement("li");\n    li.textContent = `${item.name}: ${item.price.toLocaleString("en-US")}`;\n    lines.append(li);\n  }\n  const sum = cart.reduce((s, i) => s + i.price, 0);\n  total.textContent = sum.toLocaleString("en-US");\n}\nfunction add(name, price) {\n  cart.push({ name, price });\n  localStorage.setItem("cart", JSON.stringify(cart));\n  render();\n}\n\ndocument.querySelector("#add-plain").addEventListener("click", () => add("Plain", 3000));\ndocument.querySelector("#add-chicken").addEventListener("click", () => add("Chicken", 7000));\nrender();\n',
        },
